"""Public command formatting for private guided-analysis helpers."""

from __future__ import annotations

import os
import shlex
from pathlib import Path

DEFAULT_ROUTINE = "paperclip-meta-analysis"
ROUTINE_NAMES = {DEFAULT_ROUTINE, "paperclip-meta-analysis-scale"}


def routine_command(
    operation: str,
    *arguments: str,
    directory: str | Path | None = None,
) -> str:
    """Return the supported wrapper command for one helper operation."""
    routine = os.getenv("PAPERCLIP_ROUTINE_NAME", DEFAULT_ROUTINE)
    if routine not in ROUTINE_NAMES:
        routine = DEFAULT_ROUTINE
    command = ["paperclip", "routines", "run", routine, operation, *arguments]
    if directory is not None:
        command.extend(["--dir", str(directory)])
    return shlex.join(command)
